<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Teacher Assignments</span></nav><h1>Teacher Assignments</h1><p>Authorize teachers for a whole class, homeroom, or a specific subject.</p></div></header><form class="module-card" method="post" action="<?=url('/admin/teacher-assignments')?>"><?=csrf_field()?><header class="module-card__header"><h2>New Assignment</h2></header><div class="module-card__body"><div class="module-form-grid module-form-grid--four"><div class="module-field"><label>Teacher</label><select class="module-select" name="employee_id" required><option value="">Select teacher</option><?php foreach($teachers as$t):if($t['role']!=='Teacher'&&$t['role']!=='Principal')continue;?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach?></select></div><div class="module-field"><label>Class</label><select class="module-select" id="assignClass" name="class_id" required><option value="">Select class</option><?php foreach($classes as$c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></div><div class="module-field"><label>Assignment</label><select class="module-select" name="assignment_type"><option value="whole_class">Whole Class</option><option value="homeroom">Class Teacher / Homeroom</option><option value="subject">Subject-wise</option></select></div><div class="module-field"><label>Subject (subject-wise only)</label><select class="module-select" name="subject_id" data-subject-filter="#assignClass"><option value="">No specific subject</option><?php foreach($classes as$c):foreach($c['subjects']??[] as$s):?><option value="<?=$s['id']?>" data-class="<?=$c['id']?>"><?=e($s['name'])?></option><?php endforeach;endforeach?></select></div></div></div><footer class="module-card__footer"><button class="btn btn--primary">Assign Teacher</button></footer></form><section class="module-card"><header class="module-card__header"><div><h2>Active Assignments</h2><p><?=count($assignments)?> scoped assignments</p></div></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Teacher</th><th>Class</th><th>Subject</th><th>Scope</th><th>Action</th></tr></thead><tbody><?php foreach($assignments as$a):?><tr><td><strong><?=e($a['teacher'])?></strong></td><td><?=e($a['class_name'])?></td><td><?=e($a['subject_name']??'All subjects')?></td><td><span class="status-badge"><?=e(ucwords(str_replace('_',' ',$a['assignment_type'])))?></span></td><td><form method="post" action="<?=url('/admin/teacher-assignments/'.$a['id'].'/delete')?>"><?=csrf_field()?><button class="class-action-button class-action-button--danger" aria-label="Remove assignment"><i data-lucide="trash-2"></i></button></form></td></tr><?php endforeach?><?php if(!$assignments):?><tr><td colspan="5"><div class="compact-empty"><h3>No assignments yet</h3><p>Assign a teacher to establish their academic scope.</p></div></td></tr><?php endif?></tbody></table></div></div></section></div></div></main>
